1	//! Prompt mode: prompts, compiled on demand from Piton, are sent to a local
2	//! coding harness as tasks, and each task's output is shown until it finishes.
3	//!
4	//! The latest task heads the view: its status as a coloured label, the hidden
5	//! anchor it was compiled from, and the compiled prompt the harness received.
6	//! Its output fills the space beneath, one table row per thing the harness
7	//! did (its text, each tool call, any error), with the kind of each as a
8	//! badge. While the task is under way, a row stands for what the harness
9	//! does next, showing a few lines of its latest raw output until its parts
10	//! are known. A small row, always shown above the header, expands into a
11	//! scrollable accordion of every
12	//! task sent, each of which opens onto its own output. A file opened
13	//! from the project tree splits the view, taking half of its width; the chat
14	//! input is never split.
15	//!
16	//! Prompts sent while the harness works wait in a queue, saved with the
17	//! project (see [`crate::prompt_queue`]), listed along the bottom of the view.
18	//!
19	//! Every task is saved with the project too (see [`crate::prompt_history`]),
20	//! and opening the project brings back the tasks sent before.
21	
22	use std::cell::Cell;
23	use std::collections::VecDeque;
24	use std::path::{Path, PathBuf};
25	use std::rc::Rc;
26	use std::sync::Arc;
27	
28	use anyhow::Result;
29	use futures::StreamExt as _;
30	use gpui_kit::assets::IconName;
31	use gpui_kit::base::ElementExt as _;
32	use gpui_kit::component::accordion::Accordion;
33	use gpui_kit::component::button::{Button, ButtonVariants as _};
34	use gpui_kit::component::highlighter::{HighlightTheme, SyntaxHighlighter};
35	use gpui_kit::component::input::Rope;
36	use gpui_kit::component::label::Label;
37	use gpui_kit::component::notification::Notification;
38	use gpui_kit::component::resizable::{ResizableState, h_resizable, resizable_panel};
39	use gpui_kit::component::skeleton::Skeleton;
40	use gpui_kit::component::spinner::Spinner;
41	use gpui_kit::component::switch::Switch;
42	use gpui_kit::component::table::{Table, TableBody, TableCell, TableHead, TableHeader, TableRow};
43	use gpui_kit::component::tag::Tag;
44	use gpui_kit::component::text::{TextView, TextViewStyle};
45	use gpui_kit::component::{
46	    ActiveTheme as _, ColorName, Icon, Sizable as _, StyledExt as _, h_flex, v_flex,
47	};
48	use gpui_kit::component::{Disableable as _, WindowExt as _};
49	use gpui_kit::prelude::FluentBuilder as _;
50	use gpui_kit::*;
51	
52	use crate::chat_input::{ChatInput, SendMode, Submit};
53	use crate::file_link::{self, OpenFile};
54	use crate::file_view::{CloseFile, FileView, OpenDefinition};
55	use crate::harness::{self, HarnessEvent};
56	use crate::hidden_anchor::{self, HiddenAnchor};
57	use crate::markdown;
58	use crate::project_directory::ProjectDirectory;
59	use crate::prompt_history::{self, RunRecord, SavedPrompt};
60	use crate::prompt_queue::{self, QueuedPrompt};
61	use crate::shell_format;
62	
63	/// The share of the width an opened file takes from the task view.
64	const FILE_SHARE: f32 = 0.5;
65	
66	/// The narrowest either side of the file split can be dragged.
67	const MIN_SPLIT_WIDTH: Pixels = px(160.);
68	
69	/// The tallest the expanded queue gets before it scrolls.
70	const MAX_QUEUE_HEIGHT: Pixels = px(240.);
71	
72	/// The tallest the compiled prompt in the header gets before it scrolls.
73	const MAX_PROMPT_HEIGHT: Pixels = px(160.);
74	
75	/// The widths of the output table's badge and status columns; the detail
76	/// column takes the rest.
77	const KIND_WIDTH: Pixels = px(130.);
78	const STATUS_WIDTH: Pixels = px(110.);
79	
80	/// How many lines of the harness's latest raw output stand in for output
81	/// that has yet to arrive, and how much of each line is kept.
82	const RAW_TAIL_LINES: usize = 3;
83	const RAW_LINE_CHARS: usize = 400;
84	
85	/// A prompt in the queue. Its hidden anchor is resolved and saved in the
86	/// background just after it is queued; until then it cannot be sent.
87	struct QueueItem {
88	    id: usize,
89	    text: SharedString,
90	    saved: Option<QueuedPrompt>,
91	}
92	
93	/// A prompt on its way to the harness.
94	enum Sending {
95	    /// Typed and sent straight away, in a mode.
96	    Now(SendMode),
97	    /// Out of the queue, saved with its anchor.
98	    Queued(QueuedPrompt),
99	}
100	
101	/// A prompt sent to the harness, and what the harness did with it.
102	struct PromptTask {
103	    /// The prompt as typed, shown until it compiles.
104	    text: SharedString,
105	    compiled: Option<Compiled>,
106	    reply: Reply,
107	    status: TaskStatus,
108	}
109	
110	/// A sent prompt once compiled.
111	struct Compiled {
112	    /// The name of the hidden anchor it was compiled from.
113	    anchor: SharedString,
114	    markdown: String,
115	}
116	
117	#[derive(Clone, Copy, Debug, PartialEq)]
118	enum TaskStatus {
119	    Compiling,
120	    Running,
121	    Done,
122	    Failed,
123	    /// From the history, with no record of what came of it.
124	    Unrecorded,
125	}
126	
127	impl TaskStatus {
128	    fn label(self) -> &'static str {
129	        match self {
130	            Self::Compiling => "Compiling",
131	            Self::Running => "Running",
132	            Self::Done => "Done",
133	            Self::Failed => "Failed",
134	            Self::Unrecorded => "Not recorded",
135	        }
136	    }
137	
138	    fn is_active(self) -> bool {
139	        matches!(self, Self::Compiling | Self::Running)
140	    }
141	
142	    /// A label in the status's colour, with the status spelled out. Uses the
143	    /// palette colours, like the output badges, as the theme's solid status
144	    /// colours are unreadable in dark mode.
145	    fn tag(self) -> Tag {
146	        Tag::color(match self {
147	            Self::Compiling => ColorName::Cyan,
148	            Self::Running => ColorName::Yellow,
149	            Self::Done => ColorName::Green,
150	            Self::Failed => ColorName::Red,
151	            Self::Unrecorded => ColorName::Gray,
152	        })
153	        .text_sm()
154	        .child(self.label())
155	    }
156	}
157	
158	impl PromptTask {
159	    fn new(text: SharedString) -> Self {
160	        Self {
161	            text,
162	            compiled: None,
163	            reply: Reply::default(),
164	            status: TaskStatus::Compiling,
165	        }
166	    }
167	
168	    /// A task from the history, as it ended: its run's output is replayed
169	    /// through the harness's parser.
170	    fn restore(saved: SavedPrompt) -> Self {
171	        let mut task = Self::new(saved.text.into());
172	        let Some(record) = saved.record else {
173	            task.reply.done = true;
174	            task.status = TaskStatus::Unrecorded;
175	            return task;
176	        };
177	        if let Some(markdown) = record.user_prompt {
178	            task.set_compiled(Compiled {
179	                anchor: saved.anchor.name().to_string().into(),
180	                markdown,
181	            });
182	        }
183	        for event in record.output.iter().flat_map(harness::parse) {
184	            task.apply(event);
185	        }
186	        if let Some(error) = record.error {
187	            task.apply(HarnessEvent::Failed(error));
188	        }
189	        task.end();
190	        task
191	    }
192	
193	    fn set_compiled(&mut self, compiled: Compiled) {
194	        self.compiled = Some(compiled);
195	        self.status = TaskStatus::Running;
196	    }
197	
198	    /// Folds a harness event into the task's output and status.
199	    fn apply(&mut self, event: HarnessEvent) {
200	        match self.reply.apply(event) {
201	            Some(error) => self.fail(error),
202	            None if self.reply.done && self.status == TaskStatus::Running => {
203	                self.status = TaskStatus::Done
204	            }
205	            None => {}
206	        }
207	    }
208	
209	    fn fail(&mut self, error: String) {
210	        self.reply.parts.push(ReplyPart::Error(error));
211	        self.status = TaskStatus::Failed;
212	    }
213	
214	    /// The run is over. One that ended without a result, as when the harness
215	    /// was stopped, failed, and nothing still running in it finished.
216	    fn end(&mut self) {
217	        if self.reply.done {
218	            return;
219	        }
220	        self.reply.done = true;
221	        self.reply.settle_tools(ToolState::Failed);
222	        if self.status != TaskStatus::Failed {
223	            self.fail("The harness stopped without a result.".into());
224	        }
225	    }
226	}
