403	impl Reply {
404	    /// Folds a harness event into the reply. Returns an error to show when the
405	    /// run failed.
406	    pub(crate) fn apply(&mut self, event: HarnessEvent) -> Option<String> {
407	        match event {
408	            HarnessEvent::Output(mut line) => {
409	                if let Some((end, _)) = line.char_indices().nth(RAW_LINE_CHARS) {
410	                    line.truncate(end);
411	                }
412	                if self.raw_tail.len() == RAW_TAIL_LINES {
413	                    self.raw_tail.pop_front();
414	                }
415	                self.raw_tail.push_back(line);
416	            }
417	            HarnessEvent::TextStarted => self.parts.push(ReplyPart::Text(String::new())),
418	            HarnessEvent::TextDelta(delta) => match self.parts.last_mut() {
419	                Some(ReplyPart::Text(text)) => text.push_str(&delta),
420	                _ => self.parts.push(ReplyPart::Text(delta)),
421	            },
422	            HarnessEvent::ToolStarted { id, name } => self.parts.push(ReplyPart::Tool(ToolCall {
423	                id,
424	                name,
425	                summary: None,
426	                state: ToolState::Running,
427	            })),
428	            HarnessEvent::ToolInput { id, summary } => {
429	                if let Some(call) = self.tool_mut(&id) {
430	                    call.summary = Some(summary);
431	                }
432	            }
433	            HarnessEvent::ToolFinished { id, is_error } => {
434	                if let Some(call) = self.tool_mut(&id) {
435	                    call.state = if is_error {
436	                        ToolState::Failed
437	                    } else {
438	                        ToolState::Done
439	                    };
440	                }
441	            }
442	            HarnessEvent::Finished { is_error, result } => {
443	                self.done = true;
444	                self.settle_tools(if is_error {
445	                    ToolState::Failed
446	                } else {
447	                    ToolState::Done
448	                });
449	                if is_error {
450	                    return Some(if result.is_empty() {
451	                        "The harness reported an error.".into()
452	                    } else {
453	                        result
454	                    });
455	                }
456	                // Nothing streamed (e.g. an older harness): show the result.
457	                if !self.has_text() && !result.is_empty() {
458	                    self.parts.push(ReplyPart::Text(result));
459	                }
460	            }
461	            HarnessEvent::Failed(error) => {
462	                self.done = true;
463	                self.settle_tools(ToolState::Failed);
464	                return Some(error);
465	            }
466	        }
467	        None
468	    }
469	
470	    /// Gives tool calls still running when the run ended the state they ended
471	    /// in, so none is left reading "running".
472	    fn settle_tools(&mut self, state: ToolState) {
473	        for part in &mut self.parts {
474	            if let ReplyPart::Tool(call) = part
475	                && call.state == ToolState::Running
476	            {
477	                call.state = state;
478	            }
479	        }
480	    }
481	
482	    fn tool_mut(&mut self, tool_id: &str) -> Option<&mut ToolCall> {
483	        self.parts.iter_mut().rev().find_map(|part| match part {
484	            ReplyPart::Tool(call) if call.id == tool_id => Some(call),
485	            _ => None,
486	        })
487	    }
488	
489	    /// Whether the run has ended, with a result or without.
490	    pub(crate) fn is_done(&self) -> bool {
491	        self.done
492	    }
493	
494	    /// Adds an error row to the end of the output.
495	    pub(crate) fn push_error(&mut self, error: String) {
496	        self.parts.push(ReplyPart::Error(error));
497	    }
498	
499	    fn has_text(&self) -> bool {
500	        self.parts
501	            .iter()
502	            .any(|part| matches!(part, ReplyPart::Text(text) if !text.trim().is_empty()))
503	    }
504	
505	    /// The rows of the output table, in the order they happened. Text with
506	    /// nothing in it is left out, unless it is the last thing in a reply still
507	    /// streaming. Until the reply is done, it ends in a row that is still
508	    /// filling in, adding a pending row if the last is already complete. Rows
509	    /// only change or are added at the end as the reply streams, so a row
510	    /// keeps its index.
511	    fn rows(&self) -> Vec<OutputRow<'_>> {
512	        let last = self.parts.len().saturating_sub(1);
513	        let mut rows: Vec<_> = self
514	            .parts
515	            .iter()
516	            .enumerate()
517	            .filter_map(|(ix, part)| match part {
518	                ReplyPart::Text(text) if text.trim().is_empty() && (self.done || ix != last) => {
519	                    None
520	                }
521	                ReplyPart::Text(text) => Some(OutputRow::Text(text)),
522	                ReplyPart::Tool(call) => Some(OutputRow::Tool(call)),
523	                ReplyPart::Error(error) => Some(OutputRow::Error(error)),
524	            })
525	            .collect();
526	        if !self.done && !rows.last().is_some_and(OutputRow::is_partial) {
527	            rows.push(OutputRow::Pending);
528	        }
529	        rows
530	    }
531	}
