779	        let saved = ProjectDirectory::get(cx)
780	            .map(|project_dir| prompt_queue::load(&project_dir))
781	            .unwrap_or_default();
782	        self.queue = saved
783	            .into_iter()
784	            .map(|saved| {
785	                self.next_queue_id += 1;
786	                QueueItem {
787	                    id: self.next_queue_id,
788	                    text: saved.text.clone().into(),
789	                    saved: Some(saved),
