797	    /// Replaces the tasks with those sent before in the current project, read
798	    /// in the background. Tasks are only replaced while the harness is free,
799	    /// so a run's task keeps its index; otherwise the history loads once the
800	    /// run is over, the run's own task among it.
801	    fn load_history(&mut self, cx: &mut Context<Self>) {
802	        if self.working {
803	            self.history_stale = true;
804	            return;
805	        }
806	        self.history_stale = false;
807	        let Some(project_dir) = ProjectDirectory::get(cx) else {
808	            self._history_load = Task::ready(());
809	            return;
810	        };
811	        let load = cx.background_spawn(async move {
812	            prompt_history::load(&project_dir)
813	                .into_iter()
814	                .map(PromptTask::restore)
815	                .collect::<Vec<_>>()
816	        });
817	        self._history_load = cx.spawn(async move |this, cx| {
818	            let tasks = load.await;
819	            this.update(cx, |this, cx| {
820	                if this.working {
821	                    this.history_stale = true;
822	                    return;
823	                }
824	                this.tasks = tasks;
825	                this.open_task = None;
826	                this.output_scroll.set_offset(point(px(0.), px(0.)));
827	                cx.notify();
828	            })
829	            .ok();
830	        });
831	    }
