841	    /// Adds `text` to the end of the queue, then resolves its hidden anchor,
842	    /// with the system prompt of `mode`, and saves it with the project in the
843	    /// background.
844	    fn enqueue(
845	        &mut self,
846	        text: String,
847	        mode: SendMode,
848	        window: &mut Window,
849	        cx: &mut Context<Self>,
850	    ) {
851	        let Some(project_dir) = ProjectDirectory::get(cx) else {
852	            return;
853	        };
854	        self.next_queue_id += 1;
855	        let id = self.next_queue_id;
856	        self.queue.push(QueueItem {
857	            id,
858	            text: text.clone().into(),
859	            saved: None,
860	        });
861	        cx.notify();
862	
863	        let lsp = self.chat_input.read(cx).lsp();
864	        let save = cx.background_spawn({
865	            let project_dir = project_dir.clone();
866	            async move {
867	                let mut anchor = match lsp {
868	                    Some(lsp) => lsp.anchor_for(&text)?,
869	                    None => HiddenAnchor::random(),
870	                };
871	                anchor.system_prompt = Some(hidden_anchor::system_prompt(mode, &project_dir)?);
872	                prompt_queue::add(anchor, text, &project_dir)
873	            }
874	        });
875	        cx.spawn_in(window, async move |this, cx| {
876	            let saved = save.await;
877	            this.update_in(cx, |this, window, cx| {
878	                this.queue_saved(id, saved, &project_dir, window, cx)
879	            })
880	            .ok();
881	        })
882	        .detach();
883	    }
