885	    fn queue_saved(
886	        &mut self,
887	        id: usize,
888	        saved: Result<QueuedPrompt>,
889	        project_dir: &std::path::Path,
890	        window: &mut Window,
891	        cx: &mut Context<Self>,
892	    ) {
893	        let Some(ix) = self.queue.iter().position(|item| item.id == id) else {
894	            // Cancelled while it was saved. A queue left behind by switching
895	            // projects keeps it, for when that project is opened again.
896	            if let Ok(saved) = saved
897	                && ProjectDirectory::get(cx).as_deref() == Some(project_dir)
898	            {
899	                prompt_queue::remove(&saved.file).ok();
900	            }
901	            return;
902	        };
903	        match saved {
904	            Ok(saved) => {
905	                self.queue[ix].saved = Some(saved);
906	                self.auto_send_next(cx);
907	            }
908	            Err(err) => {
909	                self.queue.remove(ix);
910	                window.push_notification(
911	                    Notification::error(format!("{err:#}")).title("Could not queue the prompt"),
912	                    cx,
913	                );
914	            }
915	        }
916	        cx.notify();
917	    }
