919	    /// Sends the first queued prompt, if the harness is free and it is saved.
920	    fn send_next(&mut self, cx: &mut Context<Self>) {
921	        // Without a project it could not be sent, and must stay queued.
922	        if self.working
923	            || ProjectDirectory::get(cx).is_none()
924	            || !self.queue.first().is_some_and(|item| item.saved.is_some())
925	        {
926	            return;
927	        }
928	        let item = self.queue.remove(0);
929	        if self.queue.is_empty() {
930	            self.queue_held = false;
931	        }
932	        let Some(saved) = item.saved else { return };
933	        self.start(item.text.to_string(), Sending::Queued(saved), cx);
934	    }
