943	    /// Removes a prompt that has not been sent from the queue, and its file.
944	    fn cancel(&mut self, id: usize, window: &mut Window, cx: &mut Context<Self>) {
945	        let Some(ix) = self.queue.iter().position(|item| item.id == id) else {
946	            return;
947	        };
948	        let item = self.queue.remove(ix);
949	        if let Some(saved) = &item.saved
950	            && let Err(err) = prompt_queue::remove(&saved.file)
951	        {
952	            // Its file is still there, so it is still queued.
953	            self.queue.insert(ix, item);
954	            window.push_notification(
955	                Notification::error(format!("{err:#}")).title("Could not cancel the prompt"),
956	                cx,
957	            );
958	        }
959	        if self.queue.is_empty() {
960	            self.queue_held = false;
961	        }
962	        cx.notify();
963	    }
