983	    /// Sends `text` to the harness as a new task: a queued prompt with the
984	    /// anchor it was saved with, else with a freshly resolved one.
985	    fn start(&mut self, text: String, sending: Sending, cx: &mut Context<Self>) {
986	        let Some(project_dir) = ProjectDirectory::get(cx) else {
987	            return;
988	        };
989	        let task_ix = self.push_task(text.clone().into(), cx);
990	        self.working = true;
991	        self.chat_input
992	            .update(cx, |input, cx| input.set_busy(true, cx));
993	
994	        let lsp = self.chat_input.read(cx).lsp();
995	        let compile = cx.background_spawn({
996	            let project_dir = project_dir.clone();
997	            async move {
998	                let anchor = match sending {
999	                    // Out of the queue first, so it is never sent twice.
1000	                    Sending::Queued(queued) => {
1001	                        prompt_queue::remove(&queued.file)?;
1002	                        queued.anchor
1003	                    }
1004	                    // Without `piton lsp` nothing is imported, and any spec
1005	                    // name the prompt uses fails to compile with an explicit
1006	                    // error.
1007	                    Sending::Now(mode) => {
1008	                        let mut anchor = match lsp {
1009	                            Some(lsp) => lsp.anchor_for(&text)?,
1010	                            None => HiddenAnchor::random(),
1011	                        };
1012	                        anchor.system_prompt =
1013	                            Some(hidden_anchor::system_prompt(mode, &project_dir)?);
1014	                        anchor
1015	                    }
1016	                };
1017	                let file = hidden_anchor::save(&anchor, &text, &project_dir)?;
1018	                let compiled = hidden_anchor::compile(&anchor, &file, &project_dir);
1019	                anyhow::Ok((anchor.name().to_string(), file, compiled))
1020	            }
1021	        });
1022	
1023	        self._pending = cx.spawn(async move |this, cx| {
1024	            // What came of the prompt, saved beside it in the history once it
1025	            // is over.
1026	            let mut record = RunRecord::default();
1027	            let mut prompt_file = None;
1028	            let compiled = compile.await.and_then(|(anchor, file, compiled)| {
1029	                prompt_file = Some(file);
1030	                Ok((anchor, compiled?))
1031	            });
1032	            match compiled {
1033	                Ok((anchor, compiled)) => {
1034	                    let prompt = compiled.user_prompt;
1035	                    record.user_prompt = Some(prompt.clone());
1036	                    let mut events =
1037	                        harness::send(prompt.clone(), compiled.system_prompt, project_dir);
1038	                    if this
1039	                        .update(cx, |this, cx| {
1040	                            this.show_compiled(task_ix, anchor, prompt, cx)
1041	                        })
1042	                        .is_err()
1043	                    {
1044	                        return;
1045	                    }
1046	                    while let Some(event) = events.next().await {
1047	                        record.note(&event);
1048	                        if this
1049	                            .update(cx, |this, cx| this.apply_event(task_ix, event, cx))
1050	                            .is_err()
1051	                        {
1052	                            return;
1053	                        }
1054	                    }
1055	                }
1056	                Err(err) => {
1057	                    let error = format!("{err:#}");
1058	                    record.error = Some(error.clone());
1059	                    this.update(cx, |this, _| {
1060	                        if let Some(task) = this.tasks.get_mut(task_ix) {
1061	                            task.fail(error);
1062	                        }
1063	                    })
1064	                    .ok();
1065	                }
1066	            }
1067	
1068	            // Unsaved (the prompt itself could not be saved) there is nothing
1069	            // to save it beside.
1070	            let saved = match prompt_file {
1071	                Some(file) => {
1072	                    cx.background_spawn(async move { prompt_history::save_record(&file, &record) })
1073	                        .await
1074	                }
1075	                None => Ok(()),
1076	            };
1077	
1078	            this.update(cx, |this, cx| {
1079	                if let Some(task) = this.tasks.get_mut(task_ix) {
1080	                    task.end();
1081	                    if let Err(err) = saved {
1082	                        // Shown without failing the task: the run itself is
1083	                        // unaffected.
1084	                        task.reply.parts.push(ReplyPart::Error(format!(
1085	                            "Could not save this task to the history: {err:#}"
1086	                        )));
1087	                    }
1088	                }
1089	                this.working = false;
1090	                if this.history_stale {
1091	                    this.load_history(cx);
1092	                }
1093	                this.chat_input
1094	                    .update(cx, |input, cx| input.set_busy(false, cx));
1095	                // Deferred: starting the next run replaces this task.
1096	                let prompt_mode = cx.entity();
1097	                cx.defer(move |cx| prompt_mode.update(cx, |this, cx| this.auto_send_next(cx)));
1098	                cx.notify();
1099	            })
1100	            .ok();
1101	        });
1102	    }
