1454	/// `text` with the project directory written relative to it: paths inside the
1455	/// directory lose its path, and the directory itself reads `.`. A path that
1456	/// only starts with the same characters, like a sibling directory, is kept.
1457	fn relative_to_project(text: &str, project_dir: Option<&Path>) -> String {
1458	    let Some(dir) = project_dir
1459	        .and_then(Path::to_str)
1460	        .map(|dir| dir.trim_end_matches('/'))
1461	        .filter(|dir| !dir.is_empty())
1462	    else {
