1464	    };
1465	    let is_path_char = |c: char| c.is_alphanumeric() || matches!(c, '/' | '.' | '_' | '-' | '~');
1466	    let ends_path = |rest: &str| rest.chars().next().is_none_or(|c| !is_path_char(c));
1467	
