65	/// The tint at `position` between the tabs: red at Code (0), blue at Spec
66	/// (2), purple for both (1), where they meet, and green at Ask (3).
67	fn tint(red: Hsla, blue: Hsla, green: Hsla, position: f32) -> Hsla {
68	    if position > 2. {
69	        blend(blue, green, position - 2.)
70	    } else {
71	        blend(red, blue, position / 2.)
72	    }
73	}
