75	/// `from` blended `t` of the way to `to`, at the tint's opacity.
76	fn blend(from: Hsla, to: Hsla, t: f32) -> Hsla {
77	    let t = t.clamp(0., 1.);
78	    // The shorter way round the hue circle, which from red to blue passes
79	    // through purple rather than green.
80	    let hue_step = (to.h - from.h + 0.5).rem_euclid(1.) - 0.5;
81	    Hsla {
82	        h: (from.h + hue_step * t).rem_euclid(1.),
83	        s: from.s + (to.s - from.s) * t,
84	        l: from.l + (to.l - from.l) * t,
85	        a: TINT_OPACITY,
86	    }
87	}
