648	/// Completions for the chat input: harness mentions after `/` or `@`, and
649	/// Piton from `piton lsp`, when it is running, everywhere else.
650	struct PromptCompletions {
651	    lsp: Option<Arc<PitonSession>>,
652	}
653	
654	impl CompletionProvider for PromptCompletions {
655	    fn completions(
656	        &self,
657	        text: &Rope,
658	        offset: usize,
659	        _: CompletionContext,
660	        _: &mut Window,
661	        cx: &mut App,
662	    ) -> Task<Result<CompletionResponse>> {
663	        let lsp = self.lsp.clone();
664	        let prompt = text.to_string();
665	        let project_dir = ProjectDirectory::get(cx);
666	        cx.background_spawn(async move {
667	            if harness_mentions::mention_at(&prompt, offset).is_some() {
668	                let invocables = harness_mentions::discover(project_dir.as_deref());
669	                let items = harness_mentions::complete(&prompt, offset, &invocables);
670	                return Ok(CompletionResponse::Array(items.unwrap_or_default()));
671	            }
672	            // A slash or hyphen only triggers completion inside a mention.
673	            let typed = prompt
674	                .get(..offset)
675	                .and_then(|before| before.chars().next_back());
676	            match lsp {
677	                Some(lsp) if !matches!(typed, Some('/' | '-')) => lsp.complete(&prompt, offset),
678	                _ => Ok(CompletionResponse::Array(Vec::new())),
679	            }
680	        })
681	    }
682	
683	    fn is_completion_trigger(&self, _: usize, new_text: &str, _: &mut App) -> bool {
684	        new_text.chars().last().is_some_and(|c| {
685	            c.is_alphanumeric() || matches!(c, '{' | '.' | '$' | '@' | ':' | '_' | '/' | '-')
686	        })
687	    }
688	}
