928	            ("shift-tab", 3),
929	            ("shift-tab", 2),
930	            ("shift-tab", 1),
931	        ];
932	        for (key, expected) in presses {
933	            cx.update_window(handle, |_, window, cx| window.press(key, cx))
934	                .unwrap();
935	            cx.run_until_parked();
936	            cx.update_window(handle, |_, window, cx| {
937	                let input = chat_input.read(cx);
938	                assert_eq!(input.selected_tab, expected, "after {key}");
939	                assert_eq!(input.value(cx).as_ref(), "hi");
940	                assert!(input.is_focused(window, cx), "the input lost focus on {key}");
941	            })
942	            .unwrap();
943	        }
944	    }
945	
946	    type Bounds = gpui_kit::Bounds<gpui_kit::Pixels>;
947	
948	    /// The Code tab, the chain, and the Spec tab, as last laid out.
949	    fn chain_layout(window: &mut Window, cx: &mut gpui_kit::App) -> (Bounds, Bounds, Bounds) {
950	        window.render_frame(cx);
951	        (
952	            window.within("code-tab").find(0usize).bounds(),
953	            window.find("both-tab").bounds(),
954	            window.within("spec-tab").find(0usize).bounds(),
955	        )
956	    }
957	
958	    /// Draws frames until the gap between Code and Spec is `gap`.
959	    fn settle_chain(
960	        handle: gpui_kit::AnyWindowHandle,
961	        gap: gpui_kit::Pixels,
962	        cx: &mut TestAppContext,
963	    ) -> (Bounds, Bounds, Bounds) {
964	        let start = std::time::Instant::now();
965	        loop {
966	            let layout = cx
967	                .update_window(handle, |_, window, cx| chain_layout(window, cx))
968	                .unwrap();
969	            let (code, _, spec) = layout;
970	            if (spec.left() - code.right() - gap).abs() <= super::px(0.5) {
971	                return layout;
972	            }
973	            assert!(
974	                start.elapsed() < TIMEOUT,
975	                "the tabs did not settle {gap:?} apart: Code {code:?}, Spec {spec:?}"
976	            );
977	            std::thread::sleep(Duration::from_millis(16));
978	        }
979	    }
980	
981	    /// The chain is a square half the height of the tabs, centred on them.
982	    /// Inactive, it sits in the gap between Code and Spec, overlapping neither.
983	    /// Active, the tabs slide in until they meet beneath it, and it overlaps
984	    /// both, centred on the seam. The chain stays put throughout.
985	    #[gpui_kit::test]
986	    async fn chain_joins_the_tabs_beneath_it(cx: &mut TestAppContext) {
987	        cx.update(|cx| {
988	            gpui_kit::init(cx);
989	            piton_syntax::init();
990	            ProjectDirectory::init(cx);
991	        });
992	        let window = cx.add_window(|window, cx| {
993	            let input = cx.new(|cx| ChatInput::new(window, cx));
994	            Root::new(input, window, cx)
995	        });
996	        let handle = window.into();
997	        cx.wait_for(handle, TIMEOUT, |window, _| {
998	            window.try_find("prompt-editor").is_some()
999	        })
1000	        .await;
1001	
1002	        let (code, chain, spec) = settle_chain(handle, super::CHAIN_GAP, cx);
1003	        assert_eq!(
1004	            chain.size.width, chain.size.height,
1005	            "chain {chain:?} is not square"
1006	        );
1007	        assert!(
1008	            (chain.size.height - code.size.height * 0.5).abs() <= super::px(0.5),
1009	            "chain {chain:?} is not half the height of Code {code:?}"
1010	        );
1011	        assert!(
1012	            (chain.center().y - code.center().y).abs() <= super::px(0.5),
1013	            "chain {chain:?} is not centred on Code {code:?}"
1014	        );
1015	        assert!(
1016	            code.right() <= chain.left() && chain.right() <= spec.left(),
1017	            "inactive chain {chain:?} overlaps Code {code:?} or Spec {spec:?}"
1018	        );
1019	        assert!(
1020	            (chain.center().x - (code.right() + spec.left()) * 0.5).abs() <= super::px(0.5),
1021	            "inactive chain {chain:?} is not centred in the gap"
1022	        );
1023	        let resting = chain;
1024	
1025	        // Tab moves to the chain; the tabs slide rather than jump together.
1026	        cx.update_window(handle, |_, window, cx| window.press("tab", cx))
1027	            .unwrap();
1028	        let (code, _, spec) = cx
1029	            .update_window(handle, |_, window, cx| chain_layout(window, cx))
1030	            .unwrap();
1031	        assert!(
1032	            spec.left() - code.right() > super::px(1.),
1033	            "the tabs met without sliding: Code {code:?}, Spec {spec:?}"
1034	        );
1035	
1036	        let (code, chain, spec) = settle_chain(handle, super::px(0.), cx);
1037	        assert_eq!(chain, resting, "the chain moved when activated");
1038	        assert!(
1039	            chain.left() < code.right() && spec.left() < chain.right(),
1040	            "active chain {chain:?} does not overlap Code {code:?} and Spec {spec:?}"
1041	        );
1042	        assert!(
1043	            (chain.center().x - code.right()).abs() <= super::px(0.5),
1044	            "active chain {chain:?} is not centred on the seam at {:?}",
1045	            code.right()
1046	        );
1047	
1048	        // Back to Code: the tabs slide apart again, around the same chain.
1049	        cx.update_window(handle, |_, window, cx| window.press("shift-tab", cx))
1050	            .unwrap();
1051	        let (_, chain, _) = settle_chain(handle, super::CHAIN_GAP, cx);
1052	        assert_eq!(chain, resting, "the chain moved when deactivated");
1053	    }
1054	
1055	    /// Code is tinted red and Spec blue, faintly, both together purple, a hue
1056	    /// between the two, and Ask green. Each tab's own tint shows only while
1057	    /// it is selected.
1058	    #[test]
1059	    fn tints_are_red_blue_and_purple_between() {
1060	        let (red, blue, green) = (gpui_kit::red(), gpui_kit::blue(), gpui_kit::green());
1061	        let (code, both, spec, ask) = (
1062	            super::tint(red, blue, green, 0.),
1063	            super::tint(red, blue, green, 1.),
1064	            super::tint(red, blue, green, 2.),
1065	            super::tint(red, blue, green, 3.),
1066	        );
1067	        let same = |a: gpui_kit::Hsla, b: gpui_kit::Hsla| {
1068	            [(a.h, b.h), (a.s, b.s), (a.l, b.l)]
1069	                .iter()
1070	                .all(|(x, y)| (x - y).abs() < 1e-4)
1071	        };
1072	        assert!(same(code, red), "Code {code:?} is not {red:?}");
1073	        assert!(same(spec, blue), "Spec {spec:?} is not {blue:?}");
1074	        assert!(same(ask, green), "Ask {ask:?} is not {green:?}");
1075	        for color in [code, both, spec, ask] {
1076	            assert_eq!(color.a, super::TINT_OPACITY);
1077	        }
1078	        // Purple sits past blue, on the way round the hue circle to red.
1079	        assert!(both.h > blue.h, "{both:?} is not between {blue:?} and {red:?}");
1080	
1081	        // Rows: Code, chain, Spec, Ask. Columns: the tint at each tab.
1082	        let shown = [
1083	            [1., 1., 0., 0.],
1084	            [0., 1., 0., 0.],
1085	            [0., 1., 1., 0.],
1086	            [0., 0., 0., 1.],
1087	        ];
1088	        for (ix, row) in shown.iter().enumerate() {
1089	            for (position, expected) in row.iter().enumerate() {
1090	                assert_eq!(
1091	                    super::tab_tint_shown(ix, position as f32),
1092	                    *expected,
1093	                    "tab {ix} with the tint at {position}"
1094	                );
1095	            }
1096	        }
1097	    }
1098	
1099	    /// With one line of text, the input is as tall as the Send button and
1100	    /// lines up with it.
1101	    #[gpui_kit::test]
1102	    async fn single_line_input_lines_up_with_send_button(cx: &mut TestAppContext) {
1103	        cx.update(|cx| {
1104	            gpui_kit::init(cx);
1105	            piton_syntax::init();
1106	            ProjectDirectory::init(cx);
1107	        });
1108	        let window = cx.add_window(|window, cx| {
1109	            let input = cx.new(|cx| ChatInput::new(window, cx));
1110	            Root::new(input, window, cx)
1111	        });
1112	        let handle = window.into();
1113	        cx.wait_for(handle, TIMEOUT, |window, _| {
1114	            window.try_find("prompt-editor").is_some()
1115	        })
1116	        .await;
1117	
1118	        cx.update_window(handle, |_, window, cx| {
1119	            // A second frame sizes the input from the editor's laid-out line height.
1120	            window.render_frame(cx);
1121	            let editor = window.find("prompt-editor").bounds();
1122	            let send = window.find("send").bounds();
1123	            assert!(
1124	                (editor.size.height - send.size.height).abs() <= gpui_kit::px(1.),
1125	                "input {editor:?} and Send {send:?} differ in height"
1126	            );
1127	            assert!(
1128	                (editor.bottom() - send.bottom()).abs() <= gpui_kit::px(1.),
1129	                "input {editor:?} and Send {send:?} are not aligned"
1130	            );
1131	        })
1132	        .unwrap();
1133	    }
1134	
1135	    /// The chat input at the bottom of the window, with a probe laid out
1136	    /// after it that notes the editor's scroll offset between prepaint and
1137	    /// paint: the offset its text is actually painted at, before paint
1138	    /// clamps it for the next frame.
1139	    struct Probed {
1140	        input: Entity<ChatInput>,
1141	        painted_scroll_y: Rc<Cell<gpui_kit::Pixels>>,
1142	    }
1143	
1144	    impl Render for Probed {
1145	        fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
1146	            let editor = self.input.read(cx).editor.clone();
1147	            let painted_scroll_y = self.painted_scroll_y.clone();
1148	            div()
1149	                .size_full()
1150	                .flex()
1151	                .flex_col()
1152	                .justify_end()
1153	                .child(self.input.clone())
1154	                .child(
1155	                    gpui_kit::canvas(
1156	                        move |_, _, cx| painted_scroll_y.set(editor.read(cx).scroll_offset().y),
1157	                        |_, _, _, _| {},
1158	                    )
1159	                    .absolute()
1160	                    .size_0(),
1161	                )
1162	        }
1163	    }
1164	
1165	    /// What one painted frame of the input looked like.
1166	    #[derive(Debug, Clone, Copy)]
1167	    struct Frame {
1168	        rows: usize,
1169	        top: gpui_kit::Pixels,
1170	        bottom: gpui_kit::Pixels,
1171	        height: gpui_kit::Pixels,
1172	        /// The offset the text was painted at in this frame.
1173	        painted_scroll_y: gpui_kit::Pixels,
1174	        /// The offset the editor kept after painting.
1175	        scroll_y: gpui_kit::Pixels,
1176	        cursor_top: gpui_kit::Pixels,
1177	        cursor_bottom: gpui_kit::Pixels,
1178	    }
1179	
1180	    /// Presses Enter in the input at the bottom of the window, `presses`
1181	    /// times, and records every frame drawn after each press, the way the
1182	    /// window draws them: only what the press invalidated, with no forced
1183	    /// refresh in between.
1184	    async fn frames_after_enter(
1185	        presses: usize,
1186	        scale_factor: f32,
1187	        cx: &mut TestAppContext,
1188	    ) -> (gpui_kit::Pixels, Vec<Vec<Frame>>) {
1189	        cx.update(|cx| {
1190	            gpui_kit::init(cx);
1191	            piton_syntax::init();
1192	            ProjectDirectory::init(cx);
1193	        });
1194	        let mut chat_input = None;
1195	        let painted = Rc::new(Cell::new(gpui_kit::px(0.)));
1196	        let window = cx.add_window(|window, cx| {
1197	            let input = cx.new(|cx| ChatInput::new(window, cx));
1198	            chat_input = Some(input.clone());
1199	            let painted_scroll_y = painted.clone();
1200	            let view = cx.new(|_| Probed {
1201	                input,
1202	                painted_scroll_y,
1203	            });
1204	            Root::new(view, window, cx)
1205	        });
1206	        let chat_input = chat_input.unwrap();
1207	        let editor = chat_input.read_with(cx, |input, _| input.editor.clone());
1208	        let handle = window.into();
1209	        // Most displays are not 2x: at other scales the rows are a fraction
1210	        // of a pixel off the device grid.
1211	        cx.simulate_window_scale_factor_change(handle, scale_factor);
1212	        cx.wait_for(handle, TIMEOUT, |_, cx| {
1213	            editor.read(cx).line_height().is_some()
1214	        })
1215	        .await;
1216	
1217	        let record = |window: &mut Window, cx: &mut gpui_kit::App| {
1218	            window.draw(cx).clear(cx);
1219	            let bounds = window.find("prompt-editor").bounds();
1220	            let editor = editor.read(cx);
1221	            let scroll_y = editor.scroll_offset().y;
1222	            // The cursor is laid out in window coordinates, before scrolling.
1223	            let (cursor, _) = editor.cursor_layout().unwrap();
1224	            let painted_scroll_y = painted.get();
1225	            Frame {
1226	                rows: editor.value().split('\n').count(),
1227	                top: bounds.top(),
1228	                bottom: bounds.bottom(),
1229	                height: bounds.size.height,
1230	                painted_scroll_y,
1231	                scroll_y,
1232	                cursor_top: cursor.top() + painted_scroll_y,
1233	                cursor_bottom: cursor.bottom() + painted_scroll_y,
1234	            }
1235	        };
1236	
1237	        cx.update_window(handle, |_, window, cx| {
1238	            editor.read(cx).focus_handle(cx).focus(window, cx);
1239	            window.render_frame(cx);
1240	            window.render_frame(cx);
1241	            window.input("x", cx);
1242	        })
1243	        .unwrap();
1244	        let line_height = editor.read_with(cx, |editor, _| editor.line_height().unwrap());
1245	
1246	        let mut presses_frames = vec![];
1247	        for _ in 0..presses {
1248	            let frames = cx
1249	                .update_window(handle, |_, window, cx| {
1250	                    let before = record(window, cx);
1251	                    window.dispatch_keystroke(gpui_kit::Keystroke::parse("enter").unwrap(), cx);
1252	                    let mut frames = vec![before];
1253	                    for _ in 0..6 {
1254	                        frames.push(record(window, cx));
1255	                    }
1256	                    frames
1257	                })
1258	                .unwrap();
1259	            cx.run_until_parked();
1260	            presses_frames.push(frames);
1261	        }
1262	        (line_height, presses_frames)
1263	    }
1264	
1265	    /// Enter grows the input by one row in the very next frame, and it stays
1266	    /// put from then on: the bottom edge never moves, the first line never
1267	    /// scrolls out of view, and the cursor is always inside the input.
1268	    async fn assert_enter_grows_without_flicker(scale_factor: f32, cx: &mut TestAppContext) {
1269	        let (line_height, presses) = frames_after_enter(MAX_ROWS + 3, scale_factor, cx).await;
1270	        let bottom = presses[0][0].bottom;
1271	        let one_row = presses[0][0].height;
1272	        for (press, frames) in presses.iter().enumerate() {
1273	            let rows = frames.last().unwrap().rows;
1274	            let expected = one_row + line_height * (rows.min(MAX_ROWS) - 1) as f32;
1275	            for (ix, frame) in frames.iter().enumerate().skip(1) {
1276	                let context = format!(
1277	                    "at {scale_factor}x, line height {line_height:?}, press {press}, frame {ix} of {frames:#?}"
1278	                );
1279	                assert!(
1280	                    (frame.height - expected).abs() <= gpui_kit::px(0.5),
1281	                    "height is not {expected:?} rows: {context}"
1282	                );
1283	                assert!(
1284	                    (frame.bottom - bottom).abs() <= gpui_kit::px(0.5),
1285	                    "the bottom edge moved from {bottom:?}: {context}"
1286	                );
1287	                if rows <= MAX_ROWS {
1288	                    assert!(
1289	                        frame.painted_scroll_y.abs() <= gpui_kit::px(0.5),
1290	                        "painted scrolled although everything fits: {context}"
1291	                    );
1292	                } else {
1293	                    assert!(
1294	                        (frame.painted_scroll_y - frames.last().unwrap().painted_scroll_y).abs()
1295	                            <= gpui_kit::px(0.5),
1296	                        "scroll did not settle in the first frame: {context}"
1297	                    );
1298	                }
1299	                assert!(
1300	                    frame.cursor_top >= frame.top - gpui_kit::px(0.5)
1301	                        && frame.cursor_bottom <= frame.bottom + gpui_kit::px(0.5),
1302	                    "the cursor is outside the input: {context}"
1303	                );
1304	            }
1305	        }
1306	    }
1307	
1308	    #[gpui_kit::test]
1309	    async fn enter_grows_the_input_without_flicker_at_1x(cx: &mut TestAppContext) {
1310	        assert_enter_grows_without_flicker(1.0, cx).await;
1311	    }
1312	
1313	    #[gpui_kit::test]
1314	    async fn enter_grows_the_input_without_flicker_at_1_25x(cx: &mut TestAppContext) {
1315	        assert_enter_grows_without_flicker(1.25, cx).await;
1316	    }
1317	
1318	    #[gpui_kit::test]
1319	    async fn enter_grows_the_input_without_flicker_at_1_5x(cx: &mut TestAppContext) {
1320	        assert_enter_grows_without_flicker(1.5, cx).await;
1321	    }
1322	
1323	    #[gpui_kit::test]
1324	    async fn enter_grows_the_input_without_flicker_at_1_75x(cx: &mut TestAppContext) {
1325	        assert_enter_grows_without_flicker(1.75, cx).await;
1326	    }
1327	
1328	    #[gpui_kit::test]
1329	    async fn enter_grows_the_input_without_flicker_at_2x(cx: &mut TestAppContext) {
1330	        assert_enter_grows_without_flicker(2.0, cx).await;
1331	    }
1332	
1333	    /// The input grows a row for each line and for each soft wrap of a long
1334	    /// line, and shrinks back when the text goes.
1335	    #[gpui_kit::test]
1336	    async fn input_grows_and_shrinks_with_its_text(cx: &mut TestAppContext) {
1337	        cx.update(|cx| {
1338	            gpui_kit::init(cx);
1339	            piton_syntax::init();
1340	            ProjectDirectory::init(cx);
1341	        });
1342	        let mut chat_input = None;
1343	        let window = cx.add_window(|window, cx| {
1344	            let input = cx.new(|cx| ChatInput::new(window, cx));
1345	            chat_input = Some(input.clone());
1346	            Root::new(input, window, cx)
1347	        });
1348	        let chat_input = chat_input.unwrap();
1349	        let editor = chat_input.read_with(cx, |input, _| input.editor.clone());
1350	        let handle = window.into();
1351	        cx.wait_for(handle, TIMEOUT, |window, _| {
1352	            window.try_find("prompt-editor").is_some()
1353	        })
1354	        .await;
1355	
1356	        let set_text = |text: String, cx: &mut TestAppContext| {
1357	            cx.update_window(handle, |_, window, cx| {
1358	                editor.update(cx, |editor, cx| editor.set_value(text, window, cx));
1359	                // Lay out the text, then fit the input to it.
1360	                for _ in 0..3 {
1361	                    window.render_frame(cx);
1362	                }
1363	                let line_height = editor.read(cx).line_height().unwrap();
1364	                let height = window.find("prompt-editor").bounds().size.height;
1365	                (height, line_height)
1366	            })
1367	            .unwrap()
1368	        };
1369	
1370	        let (one_row, line_height) = set_text(String::new(), cx);
1371	
1372	        let (three_lines, _) = set_text("one\ntwo\nthree".into(), cx);
1373	        assert!(
1374	            (three_lines - one_row - line_height * 2.).abs() <= gpui_kit::px(1.),
1375	            "three lines: {three_lines:?}, one row: {one_row:?}, line height: {line_height:?}"
1376	        );
1377	
1378	        let (wrapped, _) = set_text("a long line that has to wrap ".repeat(40), cx);
1379	        assert!(
1380	            wrapped >= one_row + line_height * 2.,
1381	            "one long line did not grow the input: {wrapped:?} vs one row {one_row:?}"
1382	        );
1383	        let editor_width = cx
1384	            .update_window(handle, |_, window, _| {
1385	                window.find("prompt-editor").bounds().size.width
1386	            })
1387	            .unwrap();
1388	        assert!(
1389	            editor_width
1390	                <= cx
1391	                    .update_window(handle, |_, window, _| window.viewport_size().width)
1392	                    .unwrap(),
1393	            "the input got wider than the window instead of wrapping"
1394	        );
1395	
1396	        let (cleared, _) = set_text(String::new(), cx);
1397	        assert!(
1398	            (cleared - one_row).abs() <= gpui_kit::px(1.),
1399	            "cleared input did not shrink back: {cleared:?} vs {one_row:?}"
1400	        );
1401	    }
1402	}
