1770	/// arrive: a line for each of its last few events, newest last, highlighted as
1771	/// JSON and cut off at the cell's edge. It is always as tall as a full tail, so
1772	/// the row keeps its height as lines stream in.
1773	fn raw_tail(reply: &Reply, cx: &App) -> AnyElement {
1774	    let theme = cx.theme();
