1	//! The prompt history on disk. Each sent prompt is saved in the project's
2	//! `.suspense/history` as its hidden anchor's source (see
3	//! [`crate::hidden_anchor::save`]). Once its run is over, what came of it is
4	//! saved beside it in a `.json` file of the same name: the compiled prompt the
5	//! harness received, the harness's output line by line, and any error. Opening
6	//! the project again replays them into the tasks they were.
7	
8	use std::fs;
9	use std::path::{Path, PathBuf};
10	
11	use anyhow::{Context as _, Result};
12	use serde::{Deserialize, Serialize};
13	use serde_json::Value;
14	
15	use crate::harness::HarnessEvent;
16	use crate::hidden_anchor::{self, HiddenAnchor};
17	
18	/// What came of a sent prompt, as saved beside it.
19	#[derive(Debug, Default, PartialEq, Serialize, Deserialize)]
20	#[serde(rename_all = "camelCase")]
21	pub struct RunRecord {
22	    /// The compiled `userPrompt` the harness received; none if the prompt did
23	    /// not compile.
24	    #[serde(default, skip_serializing_if = "Option::is_none")]
25	    pub user_prompt: Option<String>,
26	    /// Each line the harness printed, as JSON where it was, else as a string.
27	    #[serde(default)]
28	    pub output: Vec<Value>,
29	    /// Why the run failed, when the harness's output does not say.
30	    #[serde(default, skip_serializing_if = "Option::is_none")]
31	    pub error: Option<String>,
32	}
33	
34	impl RunRecord {
35	    /// Keeps what of a harness event cannot be replayed from its output: the
36	    /// raw lines themselves, and a failure outside them.
37	    pub fn note(&mut self, event: &HarnessEvent) {
38	        match event {
39	            HarnessEvent::Output(line) => self
40	                .output
41	                .push(serde_json::from_str(line).unwrap_or_else(|_| Value::String(line.clone()))),
42	            HarnessEvent::Failed(error) => self.error = Some(error.clone()),
43	            _ => {}
44	        }
45	    }
46	}
47	
48	/// A prompt in the history, and its run's record if one was saved.
49	pub struct SavedPrompt {
50	    pub anchor: HiddenAnchor,
51	    pub text: String,
52	    pub record: Option<RunRecord>,
53	}
54	
55	/// The record file saved beside `prompt_file`.
56	fn record_path(prompt_file: &Path) -> PathBuf {
57	    prompt_file.with_extension("json")
58	}
59	
60	/// Saves `record` beside the history file of the prompt it came of.
61	pub fn save_record(prompt_file: &Path, record: &RunRecord) -> Result<()> {
62	    let file = record_path(prompt_file);
63	    let json = serde_json::to_string_pretty(record)?;
64	    fs::write(&file, json).with_context(|| format!("could not save {}", file.display()))
65	}
66	
67	/// The project's prompt history, oldest first. Files that do not read back as
68	/// a hidden anchor are left out; a record that is missing or does not read
69	/// back is `None`.
70	pub fn load(project_dir: &Path) -> Vec<SavedPrompt> {
71	    let Ok(entries) = fs::read_dir(hidden_anchor::history_dir(project_dir)) else {
72	        return Vec::new();
73	    };
74	    let mut files: Vec<(u64, PathBuf)> = entries
75	        .filter_map(|entry| Some(entry.ok()?.path()))
76	        .filter(|path| path.extension().is_some_and(|ext| ext == "pi"))
77	        .map(|path| (sent_at(&path), path))
78	        .collect();
79	    files.sort();
80	    files
81	        .into_iter()
82	        .filter_map(|(_, file)| {
83	            let (anchor, text) = HiddenAnchor::parse(&fs::read_to_string(&file).ok()?)?;
84	            let record = fs::read_to_string(record_path(&file))
85	                .ok()
86	                .and_then(|json| serde_json::from_str(&json).ok());
87	            Some(SavedPrompt {
88	                anchor,
89	                text,
90	                record,
91	            })
92	        })
93	        .collect()
94	}
95	
96	/// When a history file was sent, from the seconds its name starts with. Not
97	/// zero-padded, so compared as numbers rather than names.
98	fn sent_at(file: &Path) -> u64 {
99	    file.file_name()
100	        .and_then(|name| name.to_str()?.split_once('-')?.0.parse().ok())
101	        .unwrap_or(0)
102	}
103	
104	#[cfg(test)]
105	mod tests {
106	    use std::fs;
107	    use std::path::Path;
108	
109	    use super::{RunRecord, load, save_record};
110	    use crate::harness::HarnessEvent;
111	    use crate::hidden_anchor::{self, HiddenAnchor};
112	
113	    /// A saved prompt loads back with the record saved beside it; one without
114	    /// a record loads back without one.
115	    #[test]
116	    fn prompts_load_back_with_their_records() {
117	        let project_dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("target/prompt-history-test");
